/* The addrtype resolution inputs (§2.3.11). Each ATOM is a module entry an
 * ADDR slot reads, named by the predicate the spec wrote and the operand that
 * indexes it; a slot is i64 when EVERY atom it names is — memory.copy's length
 * is 64-bit only when both memories are. */
typedef struct { const char* pred; const char* ident; uint8_t operand; } jav_addr_atom_t;
typedef struct {
    uint16_t                sig;        /* declared signature id */
    uint8_t                 natoms;
    const jav_addr_atom_t*   atoms;
    uint8_t                 param_atoms[JAV_SIG_MAX_PARAMS];  /* atom bitmask per param */
    /* Slots the spec types alike, params then results: same group, same class.
     * A POLY result in a group an input also belongs to takes that input's
     * class — which is how select's three §3.4.1 `t` slots stay one type. -1
     * for a slot that is not polymorphic. */
    int8_t                  poly_group[JAV_SIG_MAX_PARAMS + JAV_SIG_MAX_RESULTS];
    int8_t                  variadic;   /* param index of the variadic group, -1 if none */
    uint8_t                 present;
} jav_opcode_sig_t;

